'use client';
import Link from 'next/link';
import { useCallback, useEffect, useState } from 'react';
import { Utensils, Plus, RefreshCw, Heart, AlertCircle, Sparkles } from 'lucide-react';
import { formatMajorInput, formatMinor, parseMoneyToMinor } from '../../lib/finance/money';
import { decimal } from '../../lib/meals/engine';
import '../../app/admin/meals.css';

type View='overview'|'foods'|'planner'|'tracking'|'profile'|'history'|'spending'|'settings';
type Row=Record<string, any>;
type Snapshot={foods?:Row[];nutritionProfiles?:Row[];inventoryLots?:Row[];plans?:Row[];planItems?:Row[];consumptionEvents?:Row[];profile?:Row|null;budgets?:Row[];favorites?:Row[];progressRecords?:Row[];analytics?:Row|null;settings?:Row|null;energyEstimate?:Row|null;financeLinks?:Row[];hydrationEvents?:Row[]};
const sections:[View,string,string][]=[['overview','Overview','/admin/meals'],['foods','Food catalog','/admin/meals/foods'],['planner','Daily planner','/admin/meals/planner'],['tracking','Nutrition tracking','/admin/meals/tracking'],['profile','Body profile','/admin/meals/profile'],['history','History','/admin/meals/history'],['spending','Spending','/admin/meals/spending'],['settings','Settings','/admin/meals/settings']];
const titles:Record<View,string>={overview:'Meals & Nutrition',foods:'Food catalog',planner:'Daily planner',tracking:'Nutrition tracking',profile:'Body profile',history:'History',spending:'Spending',settings:'Settings'};
const asArray=(v:unknown):Row[]=>Array.isArray(v)?v.filter(x=>x&&typeof x==='object'):[];
const val=(o:Row,k:string)=>o?.[k]??o?.[k.replace(/[A-Z]/g,m=>`_${m.toLowerCase()}`)]??'';
const dateToday=()=>new Date().toISOString().slice(0,10);
function Empty({children}:{children:string}){return <div className="admin-empty admin-empty-large"><Utensils size={22}/><h2>Nothing recorded yet</h2><p>{children}</p></div>}
function Field({label,children,hint}:{label:string;children:React.ReactNode;hint?:string}){return <label className="admin-field"><span>{label}</span>{children}{hint&&<small className="admin-field-hint">{hint}</small>}</label>}
export default function MealsNutritionWorkspace({view}:{view:View}){
 const [data,setData]=useState<Snapshot>({});const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [notice,setNotice]=useState('');const [financeEnabled,setFinanceEnabled]=useState(false);const [aiEnabled,setAiEnabled]=useState(false);const [sensitiveAiConsent,setSensitiveAiConsent]=useState(false);const [aiQuestion,setAiQuestion]=useState('');const [aiAnswer,setAiAnswer]=useState('');const [aiBusy,setAiBusy]=useState(false);const [sendSavedData,setSendSavedData]=useState(false);const [alternatives,setAlternatives]=useState<Row[]>([]);
 const load=useCallback(async()=>{setLoading(true);try{const r=await fetch('/api/admin/meals',{cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load Meals records.');setData(d&&typeof d==='object'?d:{});setFinanceEnabled(Boolean(d.settings?.financeIntegrationEnabled));setAiEnabled(Boolean(d.settings?.aiEnabled));setSensitiveAiConsent(Boolean(d.settings?.sensitiveAiConsent));setError('')}catch(e){setError(e instanceof Error?e.message:'Could not load Meals records.')}finally{setLoading(false)}},[]);
 useEffect(()=>{void load()},[load]);
 const post=async(action:string,payload:Row)=>{setBusy(true);setError('');setNotice('');try{const r=await fetch('/api/admin/meals',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,...payload})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not save.');setNotice('Saved.');if(action==='plan.generate')setAlternatives(asArray(d.alternatives));await load();return d}catch(e){setError(e instanceof Error?e.message:'Could not save.');return null}finally{setBusy(false)}};
 const askAssistant=async(e:React.FormEvent)=>{e.preventDefault();if(!aiQuestion.trim())return;setAiBusy(true);setError('');setAiAnswer('');try{const r=await fetch('/api/admin/meals/ai',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:aiQuestion,includeStoredData:sendSavedData})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Assistant is unavailable.');setAiAnswer(d.answer||'No answer returned.')}catch(err){setError(err instanceof Error?err.message:'Assistant is unavailable.')}finally{setAiBusy(false)}};
 const moneyLabel=(values:Record<string,string>|undefined)=>Object.entries(values||{}).map(([currency,amount])=>formatMinor(amount,currency)).join(' · ')||'No recorded spending';
 const foods=asArray(data.foods),profiles=asArray(data.nutritionProfiles),lots=asArray(data.inventoryLots),plans=asArray(data.plans),items=asArray(data.planItems),events=asArray(data.consumptionEvents),budgets=asArray(data.budgets),favs=asArray(data.favorites),progress=asArray(data.progressRecords);
 const savedProfile=data.profile||{};const profilePrefs=(savedProfile.preferences||{}) as Row;const energyEstimate=data.energyEstimate?.estimate as Row|undefined;const energyReasons=Array.isArray(data.energyEstimate?.reasons)?data.energyEstimate.reasons.filter((reason:unknown):reason is string=>typeof reason==='string'):[];const actualEnergyKcal=String(data.analytics?.actualNutrients?.energyKcal||'');const energyDifference=energyEstimate&&actualEnergyKcal?decimal.subtract(actualEnergyKcal,String(energyEstimate.kcalPerDay)):null;const linkedFinanceMonth=(data.analytics?.linkedFinanceMonth||{}) as Record<string,string>;const financeMonthComparison=Object.entries(linkedFinanceMonth).map(([currency,linked])=>({currency,linked:String(linked),mealActual:String(actualMonth[currency]||'0'),difference:(BigInt(linked)-BigInt(String(actualMonth[currency]||'0'))).toString()}));
 const todayBudget=budgets.find(row=>String(row.budgetDate).slice(0,10)===dateToday());const todayActual=(data.analytics?.today||{}) as Record<string,string>;const budgetBalance=todayBudget&&todayBudget.currency?[{currency:String(todayBudget.currency),budget:String(todayBudget.amountMinor||'0'),spent:String(todayActual[String(todayBudget.currency)]||'0'),remaining:(BigInt(String(todayBudget.amountMinor||'0'))-BigInt(String(todayActual[String(todayBudget.currency)]||'0'))).toString()}]:[];const plannedMonth=(data.analytics?.plannedMonth||{}) as Record<string,string>;const actualMonth=(data.analytics?.month||{}) as Record<string,string>;const monthComparison=Array.from(new Set([...Object.keys(plannedMonth),...Object.keys(actualMonth)])).sort().map(currency=>{const planned=BigInt(plannedMonth[currency]||'0'),actual=BigInt(actualMonth[currency]||'0');return {currency,planned:planned.toString(),actual:actual.toString(),difference:(actual-planned).toString()}});
 const content=()=>{
 if(view==='overview')return <>
  <div className="admin-stat-grid meals-stats">{[['Foods',foods.length],['Available stock lots',lots.filter(x=>Number(val(x,'availableQuantity'))>0).length],['Saved plans',plans.length],['Today’s recorded meals',data.analytics?.consumedCount??0]].map(([n,v])=><article className="admin-card admin-stat" key={String(n)}><span className="admin-stat-label">{n}</span><strong className="admin-stat-value">{v}</strong><small className="admin-stat-note">From saved records</small></article>)}</div>
  <div className="meals-spend-strip"><div><span>Today</span><strong>{moneyLabel(data.analytics?.today)}</strong></div><div><span>Last 7 days</span><strong>{moneyLabel(data.analytics?.week)}</strong></div><div><span>This month</span><strong>{moneyLabel(data.analytics?.month)}</strong></div></div>
  <div className="meals-overview-grid"><section className="admin-card admin-panel"><div className="admin-panel-head"><div><h2>Recent meal plans</h2><p>Estimated plans do not count as meals eaten.</p></div><Link className="admin-link" href="/admin/meals/planner">Open planner →</Link></div>{plans.length?plans.slice(0,3).map((plan,i)=><MealPlanCard key={plan.id??i} plan={plan} items={items.filter(x=>String(val(x,'planId'))===String(plan.id))} foods={foods.filter(x=>x.availability==='AVAILABLE')} isFavorite={favs.some(x=>String(val(x,'planId'))===String(plan.id))} busy={busy} onAccept={()=>void post('plan.accept',{planId:plan.id})} onFavorite={()=>void post('favorite.plan.set',{planId:plan.id,favorite:!favs.some(x=>String(val(x,'planId'))===String(plan.id))})} onRevise={(data)=>void post('plan.item.revise',data)}/>):<Empty>Start by adding food, a cited nutrition profile, stock and a daily budget. There are no seeded examples.</Empty>}</section>
  <section className="admin-card admin-panel"><h2>Start with your food</h2><p className="meals-note">Add what you actually have, record nutrition from a label or reference, then add the purchase lot. Piece count and total weight are separate values.</p><Link className="admin-button" href="/admin/meals/foods"><Plus size={16}/> Add food and nutrition</Link><p className="meals-note">No validated personalized calorie targets are set. Unknown nutrition stays unknown; this tool does not diagnose or prescribe.</p></section></div>
  <section className="admin-card admin-panel meals-ai-panel"><div className="admin-panel-head"><div><h2><Sparkles size={18}/> Nutrition assistant</h2><p>Optional one-turn explanation through the configured central AI provider.</p></div><span className="meals-ai-badge">{aiEnabled?'Enabled':'Off'}</span></div><p className="meals-note">The assistant does not calculate authoritative nutrition, diagnose, or prescribe. It may only cite actual saved values when you explicitly include your saved data for this question.</p><label className="meals-check meals-consent-row"><input type="checkbox" checked={sendSavedData} onChange={e=>setSendSavedData(e.target.checked)}/> Include my saved food, profile and recent meal data for this question</label>{sendSavedData&&<p className="meals-sensitive-notice">This sends the selected saved records, including dietary preferences/allergies and profile details, to the configured AI provider. Stored data is not sent unless you also enabled sensitive-data consent in Settings.</p>}<form className="meals-ai-form" onSubmit={askAssistant}><textarea className="fld" rows={3} maxLength={3000} value={aiQuestion} onChange={e=>setAiQuestion(e.target.value)} placeholder="Ask about a recorded meal or how saved nutrition values compare…" aria-label="Question for nutrition assistant"/><button className="admin-button" disabled={aiBusy||!aiQuestion.trim()||!aiEnabled}><Sparkles size={15}/>{aiBusy?'Thinking…':'Ask assistant'}</button></form>{aiAnswer&&<div className="meals-ai-answer" role="status">{aiAnswer}</div>}</section>
 </>;

 if(view==='foods')return <div className="meals-columns"><section className="admin-card admin-panel"><div className="admin-panel-head"><div><h2>Add food</h2><p>Save a catalog record and optional availability details.</p></div></div><form className="meals-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void post('food.create',{name:f.get('name'),category:f.get('category'),unit:f.get('unit'),pieceCount:f.get('pieceCount')?String(f.get('pieceCount')):undefined,totalWeight:f.get('totalWeight')?String(f.get('totalWeight')):undefined,totalWeightUnit:f.get('totalWeight')?String(f.get('totalWeightUnit')):undefined,priceMinor:f.get('price')?parseMoneyToMinor(String(f.get('price')),String(f.get('currency')||'ETB'),{allowZero:true}):null,currency:f.get('currency'),priceUnit:f.get('priceUnit'),preparation:f.get('preparation'),availability:f.get('availability'),expiresAt:f.get('expiresAt')||null,imageRef:f.get('imageRef'),notes:f.get('notes'),allergens:String(f.get('allergens')).split(',').map(s=>s.trim()).filter(Boolean),dietTags:String(f.get('dietTags')).split(',').map(s=>s.trim()).filter(Boolean),restrictions:String(f.get('restrictions')).split(',').map(s=>s.trim()).filter(Boolean)});e.currentTarget.reset()}}><Field label="Food name"><input className="fld" name="name" required maxLength={160}/></Field><div className="admin-field-row"><Field label="Category"><input className="fld" name="category"/></Field><Field label="Base quantity unit"><select className="fld" name="unit" required><option value="g">Grams (g)</option><option value="kg">Kilograms (kg)</option><option value="ml">Millilitres (ml)</option><option value="l">Litres (L)</option><option value="piece">Pieces</option><option value="serving">Named servings</option></select></Field></div><div className="admin-field-row"><Field label="Piece count (optional)"><input className="fld" name="pieceCount" type="number" min="0" step="any"/></Field><Field label="Total weight (optional)"><input className="fld" name="totalWeight" type="number" min="0" step="any"/></Field><Field label="Weight unit"><select className="fld" name="totalWeightUnit"><option value="g">g</option><option value="kg">kg</option></select></Field></div><div className="admin-field-row"><Field label="Price (optional)"><input className="fld" name="price" type="number" min="0" step="any"/></Field><Field label="Currency"><input className="fld" name="currency" maxLength={3} defaultValue="ETB"/></Field></div><div className="admin-field-row"><Field label="Price unit"><input className="fld" name="priceUnit"/></Field><Field label="Availability"><select className="fld" name="availability"><option value="AVAILABLE">Available</option><option value="UNAVAILABLE">Unavailable</option></select></Field></div><Field label="Preparation"><input className="fld" name="preparation"/></Field><Field label="Expires at"><input className="fld" name="expiresAt" type="date"/></Field><Field label="Image reference"><input className="fld" name="imageRef"/></Field><Field label="Allergens (comma-separated)"><input className="fld" name="allergens"/></Field><Field label="Diet tags (e.g. vegetarian, halal)"><input className="fld" name="dietTags"/></Field><Field label="Food restriction tags (comma-separated)"><input className="fld" name="restrictions"/></Field><Field label="Notes"><textarea className="fld" name="notes" rows={3}/></Field><button className="admin-button" disabled={busy}><Plus size={16}/> Save food</button></form><h2>Nutrition profile</h2><p className="meals-note">Enter nutrient amounts manually for the selected basis. Suggested portion is separate.</p><form className="meals-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const nutrients:Record<string,string|null>={};for(const k of ['energyKcal','proteinG','carbohydrateG','fatG','saturatedFatG','fiberG','sugarG','sodiumMg','potassiumMg','calciumMg','ironMg','vitaminAMcg','vitaminCMg','vitaminDMcg','vitaminB12Mcg','magnesiumMg','zincMg']){const value=String(f.get(k)||'').trim();nutrients[k]=value||null;}void post('nutrition-profile.save',{foodId:Number(f.get('foodId')),basisType:f.get('basisType'),servingName:f.get('servingName')||undefined,servingQuantity:f.get('servingQuantity')?String(f.get('servingQuantity')):undefined,servingUnit:f.get('servingUnit')||undefined,suggestedServingQuantity:f.get('suggestedServingQuantity')?String(f.get('suggestedServingQuantity')):undefined,suggestedServingUnit:f.get('suggestedServingUnit')||undefined,nutrients,nutrientUnits:Object.fromEntries(Object.keys(nutrients).filter(k=>nutrients[k]!==null).map(k=>[k,k.endsWith('Mcg')?'mcg':k.endsWith('Mg')?'mg':k==='energyKcal'?'kcal':'g'])),source:f.get('source'),sourceDate:f.get('sourceDate')||undefined,sourceVersion:f.get('sourceVersion')||undefined,sourceUrl:f.get('sourceUrl')||undefined,provenance:{enteredManually:true},confidence:f.get('confidence')?Number(f.get('confidence')):undefined})}}><Field label="Food"><select className="fld" name="foodId" required>{foods.map((x,i)=><option key={x.id??i} value={x.id}>{x.name||`Food ${x.id}`}</option>)}</select></Field><Field label="Basis"><select className="fld" name="basisType"><option value="100g">Per 100 g</option><option value="100ml">Per 100 ml</option><option value="serving">Per serving</option></select></Field><div className="admin-field-row"><Field label="Serving name"><input className="fld" name="servingName"/></Field><Field label="Serving quantity"><input className="fld" name="servingQuantity" type="number" min="0" step="any"/></Field></div><Field label="Serving unit"><select className="fld" name="servingUnit"><option value="">Choose if named serving</option><option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="l">L</option><option value="piece">piece</option><option value="serving">serving</option></select></Field><div className="admin-field-row"><Field label="Suggested portion quantity"><input className="fld" name="suggestedServingQuantity" type="number" min="0" step="any"/></Field><Field label="Suggested portion unit"><select className="fld" name="suggestedServingUnit"><option value="">Choose unit</option><option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="l">L</option><option value="piece">piece</option><option value="serving">serving</option></select></Field></div><div className="meals-nutrient-grid">{[['energyKcal','Energy (kcal)'],['proteinG','Protein (g)'],['carbohydrateG','Carbohydrate (g)'],['fatG','Total fat (g)'],['saturatedFatG','Saturated fat (g)'],['fiberG','Fiber (g)'],['sugarG','Sugar (g)'],['sodiumMg','Sodium (mg)'],['potassiumMg','Potassium (mg)'],['calciumMg','Calcium (mg)'],['ironMg','Iron (mg)'],['vitaminAMcg','Vitamin A (mcg)'],['vitaminCMg','Vitamin C (mg)'],['vitaminDMcg','Vitamin D (mcg)'],['vitaminB12Mcg','Vitamin B12 (mcg)'],['magnesiumMg','Magnesium (mg)'],['zincMg','Zinc (mg)']].map(([k,l])=><Field key={k} label={l}><input className="fld" name={k} type="number" min="0" step="any"/></Field>)}</div><Field label="Source (required)"><input className="fld" name="source" required defaultValue="Manual entry"/></Field><Field label="Source date"><input className="fld" name="sourceDate" type="date"/></Field><Field label="Source version"><input className="fld" name="sourceVersion"/></Field><Field label="Source URL"><input className="fld" name="sourceUrl" type="url"/></Field><p className="meals-note">Local reference: <a href="https://www.fao.org/food-composition/tables-and-databases/detail/ethiopian-food-comporition-table/en" target="_blank" rel="noreferrer">Ethiopian Food Composition Table 2025 (FAO)</a>. Enter source values manually; this application does not bulk-import the table.</p><p className="meals-note">Leave unknown nutrient values blank. Values are stored with their units, reference basis, source and confidence; blank never means zero.</p><Field label="Confidence"><input className="fld" name="confidence"/></Field><button className="admin-button" disabled={busy||!foods.length}>Save nutrition profile</button></form></section><section className="admin-card admin-panel"><div className="admin-panel-head"><div><h2>Saved foods</h2><p>{foods.length} records returned by the API.</p></div></div>{foods.length?foods.map((x,i)=><div className="meals-food-edit-row" key={x.id??i}><Record row={x}/><details><summary>Edit food record</summary><form className="meals-food-editor" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const currency=String(f.get('currency')||'ETB');const weight=String(f.get('totalWeight')||'');void post('food.update',{foodId:Number(x.id),name:String(f.get('name')),category:String(f.get('category')||'Other'),pieceCount:String(f.get('pieceCount')||'')||null,totalWeight:weight||null,totalWeightUnit:weight?String(f.get('totalWeightUnit')):null,priceMinor:String(f.get('price')||'')?parseMoneyToMinor(String(f.get('price')),currency,{allowZero:true}):null,currency,priceUnit:String(f.get('priceUnit')||'')||null,preparation:String(f.get('preparation')||'')||null,availability:f.get('availability'),expiresAt:String(f.get('expiresAt')||'')||null,imageRef:String(f.get('imageRef')||'')||null,notes:String(f.get('notes')||'')||null,allergens:String(f.get('allergens')||'').split(',').map(z=>z.trim()).filter(Boolean),dietTags:String(f.get('dietTags')||'').split(',').map(z=>z.trim()).filter(Boolean),restrictions:String(f.get('restrictions')||'').split(',').map(z=>z.trim()).filter(Boolean)})}}><div className="admin-field-row"><Field label="Food name"><input className="fld" name="name" defaultValue={x.name} required/></Field><Field label="Category"><input className="fld" name="category" defaultValue={x.category}/></Field></div><div className="admin-field-row"><Field label="Status"><select className="fld" name="availability" defaultValue={x.availability}><option value="AVAILABLE">Available</option><option value="LOW_STOCK">Low stock</option><option value="UNAVAILABLE">Unavailable</option></select></Field><Field label="Expiration"><input className="fld" type="date" name="expiresAt" defaultValue={x.expiresAt||''}/></Field><Field label="Currency"><input className="fld" name="currency" defaultValue={x.currency||'ETB'} maxLength={3}/></Field></div><div className="admin-field-row"><Field label="Piece count (independent)"><input className="fld" name="pieceCount" type="number" min="0" step="any" defaultValue={x.pieceCount||''}/></Field><Field label="Total weight"><input className="fld" name="totalWeight" type="number" min="0" step="any" defaultValue={x.totalWeight||''}/></Field><Field label="Weight unit"><select className="fld" name="totalWeightUnit" defaultValue={x.totalWeightUnit||'g'}><option value="g">g</option><option value="kg">kg</option></select></Field></div><Field label="Catalog price"><input className="fld" name="price" type="number" min="0" step="any" defaultValue={x.priceMinor&&x.currency?formatMajorInput(x.priceMinor,x.currency):''}/></Field><div className="admin-field-row"><Field label="Price unit"><input className="fld" name="priceUnit" defaultValue={x.priceUnit||''}/></Field><Field label="Preparation"><input className="fld" name="preparation" defaultValue={x.preparation||''}/></Field></div><Field label="Image/storage reference"><input className="fld" name="imageRef" defaultValue={x.imageRef||''}/></Field><Field label="Allergens (comma-separated)"><input className="fld" name="allergens" defaultValue={(x.allergens||[]).join(', ')}/></Field><Field label="Diet tags"><input className="fld" name="dietTags" defaultValue={(x.dietTags||[]).join(', ')}/></Field><Field label="Restrictions"><input className="fld" name="restrictions" defaultValue={(x.restrictions||[]).join(', ')}/></Field><Field label="Notes"><textarea className="fld" name="notes" rows={2} defaultValue={x.notes||''}/></Field><button className="admin-button-secondary" disabled={busy}>Save food edits</button></form></details></div>):<Empty>No foods have been saved. Add one using the form.</Empty>}</section></div>;
 if(view==='planner')return <div className="meals-planner-layout"><section className="admin-card admin-panel meals-budget-card"><div className="admin-panel-head"><div><h2>Today’s food budget</h2><p>Independent of Personal Finance. One amount, one date, your own currency. Planning uses eligible saved stock only; it does not assume foods can be bought.</p></div></div><form className="meals-form" onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const currency=String(fd.get('currency')||'ETB');void post('budget.save',{date:fd.get('date'),amountMinor:parseMoneyToMinor(String(fd.get('amount')||'0'),currency,{allowZero:true}),currency,mealsCount:Number(fd.get('mealsCount')||3),notes:String(fd.get('notes')||'').trim()||undefined})}}><div className="admin-field-row"><Field label="Date"><input className="fld" name="date" type="date" defaultValue={todayBudget?.budgetDate||dateToday()} required/></Field><Field label="Meals planned"><select className="fld" name="mealsCount" defaultValue={todayBudget?.mealsCount??3}>{[1,2,3,4,5,6].map(n=><option key={n} value={n}>{n}</option>)}</select></Field></div><div className="meals-budget-entry"><Field label="Available food budget"><input className="fld meals-budget-input" name="amount" type="number" min="0" step="any" defaultValue={todayBudget?formatMajorInput(todayBudget.amountMinor,String(todayBudget.currency)):'0'} required/></Field><Field label="Currency"><input className="fld" name="currency" maxLength={3} defaultValue={todayBudget?.currency||'ETB'} required/></Field></div><Field label="Special instructions or note"><textarea className="fld" name="notes" rows={2} maxLength={1000} placeholder="Optional note saved with this dated budget"/></Field><p className="meals-note">Budget saving uses exact currency minor units. Notes are stored with the date; the deterministic planner does not infer medical restrictions from free text.</p><button className="admin-button meals-generate-button" disabled={busy}><Plus size={16}/> Save daily budget</button></form><form className="meals-inline-form" onSubmit={e=>{e.preventDefault();void post('plan.generate',{date:String(new FormData(e.currentTarget).get('date'))})}}><Field label="Generate for this date"><input className="fld" type="date" name="date" defaultValue={dateToday()} required/></Field><button className="admin-button" disabled={busy||!foods.length}>Generate affordable plan</button></form>{alternatives.length>0&&<div className="meals-alternatives"><h3>Other affordable combinations</h3>{alternatives.map((x,i)=><div key={i}><strong>{String(x.name||'Alternative')}</strong><span>{String(x.cost||'')} · {JSON.stringify(x.nutrition||{})}</span></div>)}</div>}</section><section className="meals-plan-list"><h2>Plans and saved combinations</h2>{plans.length?plans.map((plan,i)=><MealPlanCard key={plan.id??i} plan={plan} items={items.filter(x=>String(val(x,'planId'))===String(plan.id))} foods={foods.filter(x=>x.availability==='AVAILABLE')} isFavorite={favs.some(x=>String(val(x,'planId'))===String(plan.id))} busy={busy} onAccept={()=>void post('plan.accept',{planId:plan.id})} onFavorite={()=>void post('favorite.plan.set',{planId:plan.id,favorite:!favs.some(x=>String(val(x,'planId'))===String(plan.id))})} onRevise={(data)=>void post('plan.item.revise',data)}/>):<Empty>No plans saved. Add foods with cited, manually reviewed nutrition profiles and current unexpired stock.</Empty>}</section></div>;

 if(view==='profile')return <div className="meals-columns"><section className="admin-card admin-panel"><h2>Body profile</h2><p className="meals-note">Age is saved as an age in years, not a birth date. BMI appears only for adults with height and a dated weight record; it is informational, not a diagnosis or target. EER uses the cited NASEM 2023 adult equation only for ages 19+ with a current height/weight, an explicitly selected biological-sex model and PAL category, and confirmed No for pregnancy/lactation and eating-disorder concern. A reported medical condition suppresses it. The estimate is not a prescription; no adult equations are applied to minors.</p><form className="meals-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void post('profile.save',{ageYears:f.get('ageYears')?Number(f.get('ageYears')):null,height:f.get('height')?String(f.get('height')):null,heightUnit:f.get('height')?f.get('heightUnit'):null,sex:f.get('sex')||null,activityLevel:f.get('activityLevel')||null,fitnessGoal:f.get('fitnessGoal')||null,preferences:String(f.get('preferences')).split(',').map(x=>x.trim()).filter(Boolean),restrictions:String(f.get('restrictions')).split(',').map(x=>x.trim()).filter(Boolean),allergies:String(f.get('allergies')).split(',').map(x=>x.trim()).filter(Boolean),mealFrequency:f.get('mealFrequency')?Number(f.get('mealFrequency')):null,pregnantOrLactating:f.get('pregnantOrLactating')==='yes'?true:f.get('pregnantOrLactating')==='no'?false:null,eatingDisorderConcern:f.get('eatingDisorderConcern')==='yes'?true:f.get('eatingDisorderConcern')==='no'?false:null,medicalCondition:f.get('medicalCondition')})}}><Field label="Age (years, optional)"><input className="fld" name="ageYears" type="number" min="0" max="120" step="1" defaultValue={savedProfile.ageYears??''}/></Field><div className="admin-field-row"><Field label="Height"><input className="fld" name="height" type="number" min="0" step="any" defaultValue={savedProfile.height??''}/></Field><Field label="Height unit"><select className="fld" name="heightUnit" defaultValue={savedProfile.heightUnit||'cm'}><option value="cm">cm</option><option value="in">in</option></select></Field></div><Field label="Biological sex for the optional EER equation"><select className="fld" name="sex" defaultValue={String(savedProfile.sex||'').toLowerCase().startsWith('f')?'female':String(savedProfile.sex||'').toLowerCase().startsWith('m')?'male':''}><option value="">Not specified</option><option value="female">Female</option><option value="male">Male</option></select></Field><Field label="Activity level" hint="For the optional energy estimate, use a named NASEM PAL category; see the linked definitions below. The category is a population estimate, not a direct activity measurement."><select className="fld" name="activityLevel" defaultValue={savedProfile.activityLevel==='sedentary'?'inactive':savedProfile.activityLevel==='light'?'low_active':savedProfile.activityLevel||''}><option value="">Not specified</option><option value="inactive">Inactive</option><option value="low_active">Low active</option><option value="active">Active</option><option value="very_active">Very active</option><option value="moderate">Moderate (legacy; select a named PAL category for EER)</option></select></Field><p className="meals-note"><a href="https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/equations-estimate-energy-requirement.html" target="_blank" rel="noreferrer">Official activity-category definitions and PAL ranges</a></p><Field label="Fitness goal"><select className="fld" name="fitnessGoal" defaultValue={profilePrefs.fitnessGoal||''}><option value="">Not specified</option><option value="weight_gain">Weight gain</option><option value="maintenance">Weight maintenance</option><option value="weight_loss">Weight loss</option><option value="balanced">Balanced nutrition</option></select></Field><Field label="Meals per day"><input className="fld" name="mealFrequency" type="number" min="1" max="10" defaultValue={profilePrefs.mealFrequency??''}/></Field>{['preferences','restrictions','allergies'].map(k=><Field label={`${k[0].toUpperCase()+k.slice(1)} (comma-separated)`} key={k}><input className="fld" name={k} defaultValue={Array.isArray(profilePrefs[k])?profilePrefs[k].join(', '):''}/></Field>)}<Field label="Pregnant or lactating"><select className="fld" name="pregnantOrLactating" defaultValue={profilePrefs.pregnantOrLactating===true?'yes':profilePrefs.pregnantOrLactating===false?'no':''}><option value="">Not specified</option><option value="yes">Yes</option><option value="no">No</option></select></Field><Field label="Eating disorder concern"><select className="fld" name="eatingDisorderConcern" defaultValue={profilePrefs.eatingDisorderConcern===true?'yes':profilePrefs.eatingDisorderConcern===false?'no':''}><option value="">Not specified</option><option value="yes">Yes</option><option value="no">No</option></select></Field><Field label="Medical condition (optional)"><textarea className="fld" name="medicalCondition" rows={2} defaultValue={profilePrefs.medicalCondition||''}/> </Field><button className="admin-button" disabled={busy}>Save profile</button></form></section><section className="admin-card admin-panel"><h2>Saved profile</h2>{data.profile?<><Record row={data.profile}/>{data.profile.bmi?.informationalOnly&&<div className="meals-bmi-card"><span>Informational BMI · adult only</span><strong>{String(data.profile.bmi.bmi)} kg/m²</strong><p>{String(data.profile.bmi.limitation)}</p></div>}{!energyEstimate&&energyReasons.length>0&&<div className="meals-eer-comparison"><strong>No adult EER estimate available</strong><ul>{energyReasons.map((reason,i)=><li key={i}>{reason}</li>)}</ul></div>}<div className="meals-profile-tags">{energyEstimate&&<p><b>Adult EER estimate</b> {String(energyEstimate.kcalPerDay)} kcal/day using latest weight recorded {data.energyEstimate?.weightRecordedAt?new Date(String(data.energyEstimate.weightRecordedAt)).toLocaleDateString():'on an unknown date'}. This is not a prescription.</p>}<p><b>Preferences</b> {(profilePrefs.preferences||[]).join(', ')||'None recorded'}</p><p><b>Allergies</b> {(profilePrefs.allergies||[]).join(', ')||'None recorded'}</p><p><b>Restrictions</b> {(data.profile.restrictions||[]).join(', ')||'None recorded'}</p></div></>:<Empty>No body profile saved.</Empty>}<h2>Record progress</h2><form className="meals-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void post('progress.record',{weight:String(f.get('weight')),weightUnit:f.get('weightUnit'),bodyFatPercent:f.get('bodyFatPercent')?String(f.get('bodyFatPercent')):undefined,measurements:f.get('measurements')?JSON.parse(String(f.get('measurements'))):{},notes:f.get('notes')||undefined,recordedAt:f.get('recordedAt')?new Date(String(f.get('recordedAt'))).toISOString():undefined})}}><div className="admin-field-row"><Field label="Weight"><input className="fld" name="weight" type="number" min="0" step="any" required/></Field><Field label="Unit"><select className="fld" name="weightUnit"><option value="kg">kg</option><option value="lb">lb</option></select></Field></div><Field label="Body fat percent"><input className="fld" name="bodyFatPercent" type="number" min="0" step="any"/></Field><Field label="Measurements (JSON object)"><input className="fld" name="measurements" placeholder="e.g. {&quot;waistCm&quot;: 82}"/></Field><Field label="Notes"><textarea className="fld" name="notes" rows={2}/></Field><Field label="Recorded at"><input className="fld" name="recordedAt" type="datetime-local"/></Field><button className="admin-button" disabled={busy}>Record progress</button></form>{progress.length>0&&<><h2>Progress trend</h2><ProgressTrend records={progress}/><h2>Progress records</h2>{progress.map((x,i)=><Record key={x.id??i} row={x}/>)}</>}</section></div>;
 if(view==='tracking')return <div className="meals-tracking-layout"><section className="admin-card admin-panel"><div className="admin-panel-head"><div><h2>Today’s actual nutrition</h2><p>Only explicitly recorded meals are counted. Blank values remain unknown.</p></div></div>{budgetBalance.length>0&&<div className="meals-budget-balance"><strong>Today’s food budget · {budgetBalance[0].currency}</strong><span>Budget {formatMinor(budgetBalance[0].budget,budgetBalance[0].currency)}</span><span>Spent {formatMinor(budgetBalance[0].spent,budgetBalance[0].currency)}</span><span className={BigInt(budgetBalance[0].remaining)<BigInt(0)?'is-over-budget':''}>Remaining {formatMinor(budgetBalance[0].remaining,budgetBalance[0].currency)}</span></div>}<div className="meals-target-placeholder"><strong>Estimated energy requirement (EER)</strong>{energyEstimate?<><span>About {String(energyEstimate.kcalPerDay)} kcal/day · NASEM 2023 adult {String(energyEstimate.sexModel)} equation · {String(energyEstimate.activityCategory)} PAL</span><p>{String(energyEstimate.interpretation)}</p><p>Equation: {String(energyEstimate.equation)}</p><p>Reported standard-error context: {String(energyEstimate.standardErrorContext)}</p>{energyDifference!==null?<p>Recorded intake minus estimate: {energyDifference.startsWith('-')?'−':'+'}{energyDifference.replace('-','')} kcal. This difference alone does not indicate whether intake is adequate.</p>:<p>No recorded calories to compare yet. Only confirmed meal records are included.</p>}<a href={String(energyEstimate.source)} target="_blank" rel="noreferrer">Read the NASEM adult equation table</a></>:<><span>No estimate is available from the saved profile.</span>{energyReasons.length>0&&<ul>{energyReasons.map((reason,i)=><li key={i}>{reason}</li>)}</ul>}<p>Adult equations are never used for minors or reported pregnancy/lactation, eating-disorder concerns, or medical conditions. BMI is not used to infer calorie or nutrient targets.</p></>}</div><div className="meals-nutrition-summary">{Object.entries(data.analytics?.actualNutrients||{}).map(([key,value])=><div key={key}><span>{key.replace(/([A-Z])/g,' $1')}</span><strong>{String(value)} {String((data.analytics?.actualNutrientUnits||{})[key]||({energyKcal:'kcal',proteinG:'g',carbohydrateG:'g',fatG:'g',saturatedFatG:'g',fiberG:'g',fibreG:'g',sugarG:'g',sodiumMg:'mg',potassiumMg:'mg',calciumMg:'mg',ironMg:'mg'} as Record<string,string>)[key]||'')}</strong></div>)}</div>{!Object.keys(data.analytics?.actualNutrients||{}).length&&<p className="meals-note">No confirmed nutrient totals available today.</p>}<p className="meals-caution">The EER is an estimate, not a prescription or a weight-gain/loss goal. A difference from it is not a nutrition diagnosis. No macro or micronutrient targets are inferred. Recommended meals are never counted as consumed.</p><section className="meals-hydration-card"><div><strong>Water recorded today</strong><span>{String(data.analytics?.hydrationTodayMl||'0')} mL · no personal hydration target is inferred.</span></div><form className="meals-hydration-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void post('hydration.record',{amountMl:String(f.get('amountMl')),idempotencyKey:crypto.randomUUID(),notes:String(f.get('notes')||'').trim()||undefined})}}><Field label="Water amount (mL)"><input className="fld" type="number" name="amountMl" min="1" step="any" required/></Field><Field label="Optional note"><input className="fld" name="notes" maxLength={500}/></Field><button className="admin-button-secondary" disabled={busy}>Record water</button></form></section><h3>Planned versus recorded</h3>{items.length?items.map((item,i)=><article className="meals-compare" key={item.id??i}><MealPlanItem row={item}/><span>{events.filter(event=>String(val(event,'planItemId'))===String(item.id)).length} actual intake event(s) linked</span></article>):<Empty>Generate a plan to see the proposed meal items here.</Empty>}</section><section className="admin-card admin-panel"><h2>Record what you ate</h2><p className="meals-note">Recording is the only action that deducts stock and updates actual nutrition/spending. You can record an unplanned meal; its nutrition is calculated only from a confirmed profile.</p><form className="meals-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void post('consumption.record',{foodId:Number(f.get('foodId')),planItemId:f.get('planItemId')?Number(f.get('planItemId')):undefined,quantity:String(f.get('quantity')),unit:f.get('unit'),mealType:f.get('mealType'),idempotencyKey:crypto.randomUUID(),notes:String(f.get('notes')||'').trim()||undefined})}}><Field label="Food"><select className="fld" name="foodId" required>{foods.map((food,i)=><option key={food.id??i} value={food.id}>{food.name} · {food.unit}</option>)}</select></Field><Field label="Accepted plan item (optional)"><select className="fld" name="planItemId"><option value="">Unplanned meal</option>{items.filter(item=>plans.some(plan=>plan.status==='ACCEPTED'&&String(plan.id)===String(val(item,'planId')))).map((item,i)=><option key={item.id??i} value={item.id}>{item.foodName} · {item.mealType}</option>)}</select></Field><div className="admin-field-row"><Field label="Quantity eaten"><input className="fld" name="quantity" type="number" min="0" step="any" required/></Field><Field label="Unit"><select className="fld" name="unit" required>{['g','kg','ml','l','piece','serving'].map(unit=><option value={unit} key={unit}>{unit}</option>)}</select></Field></div><Field label="Meal"><select className="fld" name="mealType"><option value="BREAKFAST">Breakfast</option><option value="LUNCH">Lunch</option><option value="DINNER">Dinner</option><option value="SNACK">Snack</option><option value="OTHER">Other</option></select></Field><Field label="Notes"><input className="fld" name="notes" maxLength={1000}/></Field><button className="admin-button" disabled={busy||!foods.length}>Record actual intake</button></form><h3>Recent actual meals</h3>{events.length?events.slice(0,20).map((event,i)=><Record row={{...event,foodName:foods.find(food=>food.id===event.foodId)?.name??'Unknown food'}} key={event.id??i}/>):<Empty>No actual meals recorded yet.</Empty>}<h3>Water history</h3>{asArray(data.hydrationEvents).slice(0,20).map((event,i)=><Record key={event.id??i} row={event}/>)}</section></div>;

 if(view==='history')return <section className="admin-card admin-panel"><div className="admin-panel-head"><div><h2>Meal history</h2><p>Actual consumption events with the saved nutrition and cost snapshot.</p></div></div>{events.length?events.map((event,i)=><div className="meals-history-row" key={event.id??i}><Record row={{...event,foodName:foods.find(food=>food.id===event.foodId)?.name??'Unknown food'}}/>{event.nutritionSnapshot&&<details><summary>Recorded nutrition snapshot</summary><pre>{JSON.stringify(event.nutritionSnapshot,null,2)}</pre></details>}</div>):<Empty>Nothing appears here until an actual meal is recorded.</Empty>}</section>;

 if(view==='spending')return <div className="meals-spending-layout"><section className="meals-spend-summary"><article className="admin-card meals-metric"><span>Today · actual</span><strong>{moneyLabel(data.analytics?.today)}</strong></article><article className="admin-card meals-metric"><span>Last 7 days · actual</span><strong>{moneyLabel(data.analytics?.week)}</strong></article><article className="admin-card meals-metric"><span>This month · actual</span><strong>{moneyLabel(data.analytics?.month)}</strong></article></section><section className="admin-card admin-panel"><div className="admin-panel-head"><div><h2>Daily spending · last seven days</h2><p>Amounts remain grouped by currency; no exchange rate is assumed.</p></div></div><DailySpendChart days={asArray(data.analytics?.days7)}/><p className="meals-note">The chart is a record-date overview; values are labelled per day, not normalized across different currencies.</p></section><section className="admin-card admin-panel"><h2>Efficiency from actual records</h2>{asArray(data.analytics?.efficiency).length?asArray(data.analytics?.efficiency).map((row,i)=><div className="meals-efficiency-row" key={i}><strong>{String(row.currency)}</strong><span>Average / day: {formatMinor(String(row.averageDailyMinor),String(row.currency))}</span><span>Average / recorded meal: {formatMinor(String(row.averageMealMinor),String(row.currency))}</span><span>Cost / kcal: {row.costPerKcal?`${String(row.costPerKcal)} ${String(row.currency)}`:'Unknown'}</span><span>Cost / protein gram: {row.costPerProteinGram?`${String(row.costPerProteinGram)} ${String(row.currency)}`:'Unknown'}</span></div>):<Empty>Actual cost efficiency appears after meals with known prices and nutrition are recorded.</Empty>}</section><section className="admin-card admin-panel"><h2>Planned versus actual · this month</h2>{<div className="meals-plan-actual"><div><span>Planned (saved estimates)</span><strong>{moneyLabel(data.analytics?.plannedMonth)}</strong></div><div><span>Actual (consumption records)</span><strong>{moneyLabel(data.analytics?.month)}</strong></div></div>}{monthComparison.length>0&&monthComparison.map(row=><p className="meals-month-delta" key={row.currency}>{row.currency}: {BigInt(row.difference)>BigInt(0)?'over planned by ':BigInt(row.difference)<BigInt(0)?'under planned by ':'matches plan · '}{BigInt(row.difference)!==BigInt(0)?formatMinor(BigInt(row.difference)<BigInt(0)?-BigInt(row.difference):BigInt(row.difference),row.currency):''}</p>)}<h3>Lowest recorded cost per gram of protein</h3>{asArray(data.analytics?.affordableProteinSources).length?<div className="meals-protein-sources">{asArray(data.analytics?.affordableProteinSources).map((row,i)=><div className="meals-protein-source" key={`${row.currency}-${row.foodId}-${i}`}><strong>{String(row.name)}</strong><span>{String(row.currency)} {String(row.costPerProteinGram)} / g protein</span><small>Based on recorded purchase price, reviewed nutrition data and current unexpired stock ({String(row.unit)}); excludes saved allergies/restrictions.</small></div>)}</div>:<p className="meals-note">No current, unexpired, reviewed stock with known protein and price is eligible yet.</p>}{financeEnabled&&data.analytics?.linkedFinanceMonth&&<div className="meals-finance-comparison"><h3>Linked Personal Finance · this month</h3><p className="meals-note">Only consumption records you explicitly linked are compared; no unlinked Finance records are read or shown.</p>{financeMonthComparison.length?financeMonthComparison.map(row=><p key={row.currency}><b>{row.currency}</b> linked {formatMinor(row.linked,row.currency)} · Meals actual {formatMinor(row.mealActual,row.currency)} · linked minus actual {formatMinor(row.difference,row.currency)}</p>):<p className="meals-note">No linked Finance transactions this month.</p>}</div>}<h3>Frequently recorded foods</h3>{asArray(data.analytics?.frequentFoods).length?asArray(data.analytics?.frequentFoods).map((row,i)=><Record key={i} row={row}/>):<p className="meals-note">No actual food frequency records yet.</p>}</section><section className="admin-card admin-panel"><h2>Dated budget</h2>{budgets.length?budgets.slice(0,30).map((row,i)=><Record key={row.id??i} row={row}/>):<Empty>Set a daily food budget in the planner.</Empty>}</section><section className="admin-card admin-panel"><h2>Purchase inventory</h2><form className="meals-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const currency=String(f.get('currency')||'ETB');void post('inventory.purchase',{foodId:Number(f.get('foodId')),quantity:String(f.get('quantity')),unit:f.get('unit'),pieces:f.get('pieces')?String(f.get('pieces')):undefined,weight:f.get('weight')?String(f.get('weight')):undefined,weightUnit:f.get('weight')?f.get('weightUnit')||undefined:undefined,priceMinor:parseMoneyToMinor(String(f.get('price')||'0'),currency,{allowZero:true}),currency,expiresAt:f.get('expiresAt')||undefined,notes:f.get('notes')||undefined})}}><Field label="Food"><select className="fld" name="foodId" required>{foods.map((food,i)=><option key={food.id??i} value={food.id}>{food.name} · {food.unit}</option>)}</select></Field><div className="admin-field-row"><Field label="Purchase quantity"><input className="fld" name="quantity" type="number" min="0" step="any" required/></Field><Field label="Unit"><select className="fld" name="unit">{['g','kg','ml','l','piece','serving'].map(unit=><option value={unit} key={unit}>{unit}</option>)}</select></Field></div><Field label="Optional piece count"><input className="fld" name="pieces" type="number" min="0" step="any"/></Field><div className="admin-field-row"><Field label="Total weight, if distinct"><input className="fld" name="weight" type="number" min="0" step="any"/></Field><Field label="Weight unit"><select className="fld" name="weightUnit"><option value="g">g</option><option value="kg">kg</option></select></Field></div><div className="admin-field-row"><Field label="Purchase price"><input className="fld" name="price" type="number" min="0" step="any" required/></Field><Field label="Currency"><input className="fld" name="currency" maxLength={3} defaultValue={todayBudget?.currency||'ETB'} required/></Field></div><Field label="Expiration date"><input className="fld" name="expiresAt" type="date"/></Field><Field label="Purchase note"><input className="fld" name="notes" maxLength={1000}/></Field><button className="admin-button" disabled={busy||!foods.length}>Record purchase lot</button></form><h3>Current inventory lots</h3>{lots.length?lots.map((lot,i)=><div className="meals-lot-card" key={lot.id??i}><Record row={{...lot,foodName:foods.find(food=>food.id===lot.foodId)?.name??'Unknown food'}}/><form className="meals-inline-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void post('inventory.adjust',{lotId:lot.id,quantityDelta:String(f.get('quantityDelta')),unit:lot.quantityUnit,piecesDelta:f.get('piecesDelta')?String(f.get('piecesDelta')):undefined,reason:f.get('reason'),idempotencyKey:crypto.randomUUID()})}}><Field label="Quantity adjustment (+/−)"><input className="fld" name="quantityDelta" type="number" step="any" required/></Field><Field label="Piece adjustment (+/−)"><input className="fld" name="piecesDelta" type="number" step="any"/></Field><Field label="Reason (required)"><input className="fld" name="reason" maxLength={240} required/></Field><button className="admin-button-secondary" disabled={busy}>Adjust lot</button></form></div>):<Empty>No inventory lots have been recorded.</Empty>}</section><section className="admin-card admin-panel"><h2>Personal Finance link</h2><p className="meals-note">Off by default. A Finance expense is created only when you enable the integration and explicitly confirm a recorded purchase lot. Each lot can map to at most one transaction; consuming food does not create another expense.</p><Link className="admin-link" href="/admin/meals/settings">Review Finance consent →</Link></section></div>;

 return <div className="meals-columns"><section className="admin-card admin-panel"><h2>Meals settings</h2><form className="meals-form" onSubmit={e=>{e.preventDefault();void post('settings.save',{financeIntegrationEnabled:financeEnabled,aiEnabled,sensitiveAiConsent})}}><label className="meals-check"><input type="checkbox" checked={financeEnabled} onChange={e=>setFinanceEnabled(e.target.checked)}/> Finance integration</label><label className="meals-check"><input type="checkbox" checked={aiEnabled} onChange={e=>{setAiEnabled(e.target.checked);if(!e.target.checked)setSensitiveAiConsent(false)}}/> AI enabled</label><label className="meals-check"><input type="checkbox" checked={sensitiveAiConsent} disabled={!aiEnabled} onChange={e=>setSensitiveAiConsent(e.target.checked)}/> I consent to sending selected profile/food data to the configured AI provider when explicitly checked for a question</label><button className="admin-button" disabled={busy}>Save settings</button></form><h3>Favorites</h3>{foods.map((x,i)=><button key={x.id??i} className="admin-button-secondary meals-fav" disabled={busy} onClick={()=>void post('favorite.set',{foodId:x.id,favorite:!favs.some(y=>String(val(y,'foodId'))===String(x.id))})}><Heart size={15}/>{x.name||`Food ${x.id}`} · {favs.some(y=>String(val(y,'foodId'))===String(x.id))?'Remove favorite':'Add favorite'}</button>)}<h3>Nutrition profiles</h3>{profiles.length?profiles.map((x,i)=><Record row={x} key={x.id??i}/>):<Empty>No confirmed nutrition profiles saved.</Empty>}</section><section className="admin-card admin-panel"><h2>Finance links</h2><p className="meals-note">Finance actions are hidden unless enabled in settings. Link creation is duplicate-safe.</p>{financeEnabled&&lots.map((lot,i)=>{const linked=asArray(data.financeLinks).some((link)=>String(val(link,'inventoryLotId'))===String(lot.id));const food=foods.find((item)=>String(item.id)===String(lot.foodId));return <div key={lot.id??i}><Record row={{foodName:food?.name??'Food',purchasedAt:lot.purchasedAt,priceMinor:lot.priceMinor,currency:lot.currency,purchasedQuantity:lot.purchasedQuantity,quantityUnit:lot.quantityUnit}}/>{linked?<p className="meals-note"><b>Status: Linked.</b> This purchase lot already has a Personal Finance expense.</p>:<><p className="meals-note"><b>Status: Not linked.</b> This lot has no Personal Finance expense yet; it stays Meals-only unless you confirm below.</p>{BigInt(String(lot.priceMinor||'0'))<=BigInt(0)&&<p className="meals-note">Cannot link this lot because its recorded purchase price is not positive.</p>}<button className="admin-button-secondary" disabled={busy||!lot.id||BigInt(String(lot.priceMinor||'0'))<=BigInt(0)} onClick={()=>{if(window.confirm('Create one Personal Finance expense for the full recorded purchase price of this lot? This will not create expenses for consumption events.'))void post('finance-link.create',{inventoryLotId:lot.id,confirmed:true})}}>Confirm and record purchase expense</button></>}</div>})}</section></div>
 };
 return <div className="meals-root"><header className="admin-page-header"><div><p className="admin-eyebrow">PERSONAL MANAGEMENT</p><h1 className="admin-title">{titles[view]}</h1><p className="admin-description">Plan and record meals using only your saved food, stock and nutrition data.</p></div><button className="admin-button-secondary" onClick={()=>void load()} aria-label="Refresh Meals data"><RefreshCw size={16}/> Refresh</button></header><nav className="meals-tabs" aria-label="Meals pages">{sections.map(([key,label,href])=><Link key={key} href={href} aria-current={view===key?'page':undefined} className={view===key?'active':''}>{label}</Link>)}</nav>{error&&<div className="admin-error" role="alert"><AlertCircle size={18}/>{error}</div>}{notice&&<p className="meals-success" role="status">{notice}</p>}{loading?<div className="admin-card admin-panel" aria-live="polite">Loading saved Meals records…</div>:content()}</div>
}
function Record({row}:{row:Row}){const pairs=Object.entries(row).filter(([k,v])=>!['id','createdAt','updatedAt','userId','privateNotes','birthDate'].includes(k)&&v!=null&&v!==''&&typeof v!=='object');return <article className="meals-record">{pairs.length?pairs.map(([k,v])=><span key={k}><b>{k.replace(/([A-Z])/g,' $1').replace(/^./,s=>s.toUpperCase())}</b> {['amountMinor','priceMinor','costMinor'].includes(k)&&row.currency?formatMinor(String(v),String(row.currency)):String(v)}</span>):<span>Saved record</span>}</article>}

function MealPlanItem({row}:{row:Row}){const values=row.calculatedNutrients&&typeof row.calculatedNutrients==='object'?row.calculatedNutrients as Row:{};const units=values.units&&typeof values.units==='object'?values.units as Row:{};const nutrients=Object.entries(values).filter(([k,v])=>!['source','profileVersion','confidence','provenance','units','quantity','unit','unknown'].includes(k)&&typeof v==='string'&&/^(?:0|[1-9]\d*)(?:\.\d{1,6})?$/.test(v));return <article className="meals-item-card"><div className="meals-item-main"><strong>{row.foodName||`Food ${row.foodId}`}</strong><span>{row.mealType} · {row.servingQuantity} {row.servingUnit}</span></div><div className="meals-item-nutrients">{nutrients.length?nutrients.map(([k,v])=><span key={k}><b>{k.replace(/([A-Z])/g,' $1')}</b> {v} {units[k]||''}</span>):<span>Nutrition unknown for this item.</span>}</div><small>Cost {row.costMinor&&row.currency?formatMinor(row.costMinor,row.currency):'not priced'} · Source {String(values.source||'not recorded')} · profile v{String(values.profileVersion||'—')}</small></article>}
function MealPlanCard({plan,items,foods,isFavorite,busy,onAccept,onFavorite,onRevise}:{plan:Row;items:Row[];foods:Row[];isFavorite:boolean;busy:boolean;onAccept:()=>void;onFavorite:()=>void;onRevise:(data:Row)=>void}){const snapshot=plan.nutritionSnapshot&&typeof plan.nutritionSnapshot==='object'?plan.nutritionSnapshot as Row:{};const planEer=snapshot.energyEstimate&&typeof snapshot.energyEstimate==='object'?snapshot.energyEstimate as Row:null;const energyComparison=snapshot.energyComparison&&typeof snapshot.energyComparison==='object'?snapshot.energyComparison as Row:null;const input=plan.inputSnapshot&&typeof plan.inputSnapshot==='object'?plan.inputSnapshot as Row:{};const totals=snapshot.totalNutrients&&typeof snapshot.totalNutrients==='object'?snapshot.totalNutrients as Row:{};const units=snapshot.units&&typeof snapshot.units==='object'?snapshot.units as Row:{};const totalValues=Object.entries(totals).filter(([,v])=>typeof v==='string');const editable=String(plan.status)==='DRAFT';return <article className="meals-plan-card"><header><div><p className="admin-eyebrow">{String(plan.planDate||'')}</p><h3>Daily plan</h3>{input.revisionOf&&<small>Revised from plan #{String(input.revisionOf)} · prior plan kept in history</small>}</div><span className={`meals-status meals-status-${String(plan.status||'draft').toLowerCase()}`}>{String(plan.status||'DRAFT')}</span></header><p className="meals-plan-reason">{String(snapshot.reason||'Selected using the saved budget, confirmed nutrition profiles, recorded inventory, and safety filters.')}</p><div className="meals-plan-cost"><span>Estimated spend</span><strong>{plan.costMinor&&plan.currency?formatMinor(plan.costMinor,plan.currency):'Not priced'}</strong></div><div className="meals-plan-items">{items.length?items.map((item,i)=><div className="meals-plan-item-wrap" key={item.id??i}><MealPlanItem row={item}/>{editable&&<div className="meals-item-editor"><form className="meals-item-edit-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const operation=String(f.get('operation'));const payload:Row={planId:plan.id,itemId:item.id,operation,quantity:String(f.get('quantity')),unit:String(f.get('unit'))};if(operation==='replace')payload.foodId=Number(f.get('foodId'));onRevise(payload)}}><select className="fld" name="operation" defaultValue="adjust" aria-label="Edit action"><option value="adjust">Adjust serving</option><option value="replace">Replace food</option></select><select className="fld" name="foodId" defaultValue={item.foodId} aria-label="Replacement food">{foods.map((food,j)=><option key={food.id??j} value={food.id}>{food.name}</option>)}</select><input className="fld" type="number" name="quantity" min="0" step="any" defaultValue={item.servingQuantity} required aria-label="Serving quantity"/><select className="fld" name="unit" defaultValue={item.servingUnit} aria-label="Serving unit">{['g','kg','ml','l','piece','serving'].map(unit=><option value={unit} key={unit}>{unit}</option>)}</select><button className="admin-button-secondary" disabled={busy}>Save new draft</button></form><button className="meals-remove-item" disabled={busy} onClick={()=>onRevise({planId:plan.id,itemId:item.id,operation:'remove'})}>Remove from new draft</button></div>}</div>):<p>No candidate combination passed stock, safety, measurement and budget checks.</p>}</div>{editable&&foods.length>0&&<form className="meals-add-item" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);onRevise({planId:plan.id,operation:'add',foodId:Number(f.get('foodId')),quantity:String(f.get('quantity')),unit:String(f.get('unit')),mealType:String(f.get('mealType'))})}}><strong>Add a food item to a new draft</strong><select className="fld" name="foodId">{foods.map((food,j)=><option key={food.id??j} value={food.id}>{food.name}</option>)}</select><input className="fld" name="quantity" type="number" min="0" step="any" defaultValue="1" required aria-label="New item quantity"/><select className="fld" name="unit">{['g','kg','ml','l','piece','serving'].map(unit=><option key={unit} value={unit}>{unit}</option>)}</select><select className="fld" name="mealType"><option value="SNACK">Snack</option><option value="BREAKFAST">Breakfast</option><option value="LUNCH">Lunch</option><option value="DINNER">Dinner</option></select><button className="admin-button-secondary" disabled={busy}>Add to new draft</button></form>}{totalValues.length>0&&<div className="meals-day-totals"><strong>Selected-plan totals (known values only)</strong><div>{totalValues.map(([k,v])=><span key={k}>{k.replace(/([A-Z])/g,' $1')}: {String(v)} {String(units[k]||'')}</span>)}</div></div>}{planEer&&<div className="meals-eer-comparison"><strong>Optional EER reference · {String(planEer.kcalPerDay)} kcal/day</strong><p>{energyComparison&&energyComparison.plannedEnergyKcal?`Selected plan entries total ${String(energyComparison.plannedEnergyKcal)} kcal; difference vs this reference: ${String(energyComparison.differenceKcal)} kcal.`:'No known calorie total is available for comparison.'}</p><p>{String(energyComparison?.meaning||'Informational population estimate only; not a prescription or full-day intake.')}</p><p>{String(planEer.standardErrorContext)}</p><a href={String(planEer.source)} target="_blank" rel="noreferrer">NASEM equation source</a></div>}<p className="meals-note">{String(snapshot.method||'Estimates only. No validated personal targets are available.')}</p><div className="meals-plan-actions">{editable&&<button className="admin-button" disabled={busy||!items.length} onClick={onAccept}>Accept plan</button>}<button className="admin-button-secondary" disabled={busy||!items.length} onClick={onFavorite}><Heart size={15}/>{isFavorite?'Remove favorite':'Save meal plan'}</button></div></article>}
function DailySpendChart({days}:{days:Row[]}){const currencies=Array.from(new Set(days.flatMap(day=>Object.keys((day.spend||{}) as Record<string,string>))));if(!currencies.length)return <p className="meals-note">No actual spending data for the last seven days.</p>;return <div className="meals-currency-charts">{currencies.map(currency=>{const values=days.map(day=>BigInt(String(((day.spend||{}) as Record<string,string>)[currency]||'0')));const max=values.reduce((a,b)=>a>b?a:b,BigInt(0));return <div className="meals-currency-chart" key={currency}><h3>{currency}</h3><div className="meals-daily-bars">{days.map((day,i)=>{const height=max===BigInt(0)?0:Number(values[i]*BigInt(100)/max);return <div className="meals-daily-bar" key={String(day.date)}><div className="meals-bar-track"><i style={{height:`${height}%`}}/></div><strong>{formatMinor(values[i].toString(),currency)}</strong><small>{String(day.date||'').slice(5)}</small></div>})}</div></div>})}</div>}
function ProgressTrend({records}:{records:Row[]}){const samples=records.map((r)=>{const date=String(r.recordedAt||'').slice(0,10);const kg=Number(r.weight)*(r.weightUnit==='lb'?0.45359237:1);return {date,kg}}).filter((r)=>/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&Number.isFinite(r.kg)&&r.kg>0).sort((a,b)=>a.date.localeCompare(b.date));if(samples.length<2)return <p className="meals-note">Add at least two dated weight records to see a trend; individual daily changes are not interpreted.</p>;const aggregate=(span:'week'|'month')=>{const map=new Map<string,number[]>();for(const row of samples){const d=new Date(`${row.date}T00:00:00Z`);let key:string;if(span==='month')key=row.date.slice(0,7);else{const day=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-day);key=d.toISOString().slice(0,10)}map.set(key,[...(map.get(key)||[]),row.kg])}return Array.from(map,([label,values])=>({label,value:values.reduce((a,b)=>a+b,0)/values.length})).slice(-8)};return <div className="meals-trend-grid">{(['week','month'] as const).map((span)=>{const rows=aggregate(span),min=Math.min(...rows.map(x=>x.value)),max=Math.max(...rows.map(x=>x.value));return <section className="meals-trend" key={span}><h3>{span==='week'?'Weekly':'Monthly'} average weight</h3><div className="meals-trend-bars" role="img" aria-label={`${span} average weight trend in kilograms`}>{rows.map((row)=>{const height=max===min?50:20+Math.round((row.value-min)/(max-min)*70);return <div key={row.label}><i style={{height:`${height}%`}} title={`${row.label}: ${row.value.toFixed(1)} kg`}/><small>{row.label.slice(span==='week'?5:5)}</small></div>})}</div><p className="meals-note">Averages in kg; trend context only, not a target.</p></section>})}</div>}
